def audit(value,name='native-trace.json'):
 assert name in ('native-trace.json','native-intent.json')
 p=pathlib.Path(name)
 if p.exists() or p.is_symlink():regular(p,10000000)
 fd,tmp=tempfile.mkstemp(prefix='.023-trace-',dir='.')
 try:
  with os.fdopen(fd,'w') as f:json.dump(value,f,ensure_ascii=False,sort_keys=True)
  if p.exists() or p.is_symlink():regular(p,10000000)
  os.replace(tmp,p)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)
