  if not self.cli.startswith('/') or not self.host.startswith('unix:///tmp/opsforge-s06-') or not self.expected:raise EnvironmentUnavailable('trusted private CLI/socket/EngineID absent')
  h=hashlib.sha256(pathlib.Path(self.cli).read_bytes()).hexdigest()
