 def call(self,args,check=True,timeout=15):
  a=[self.cli,'--host',self.host]+args;t=time.perf_counter()
  try:
   p=subprocess.run(a,env=self.env,capture_output=True,timeout=timeout)
  except subprocess.TimeoutExpired as e:
   self.records.append({'argv':a,'exit_code':124,'timeout':True,'seconds':time.perf_counter()-t,'stdout':(e.stdout or b'').decode(errors='replace'),'stderr':(e.stderr or b'').decode(errors='replace')});raise EnvironmentUnavailable('native command timeout')
  r={'argv':a,'exit_code':p.returncode,'stdout':p.stdout.decode(errors='replace'),'stderr':p.stderr.decode(errors='replace'),'seconds':time.perf_counter()-t};self.records.append(r)
  if check:assert p.returncode==0,r
  return r
 def sql(self,name,query,host=None,check=True):
  a=['exec',name,'psql','-X','-v','ON_ERROR_STOP=1','-U','opsforge','-d','lab','-At']
