def evaluate(s,d):
 s.network='opsforge-s06-023-net-'+s.token;s.trace['resources']['network']=s.network
 audit({'engine_id':s.expected,**s.trace['resources']},'native-intent.json')
 s.call(['network','create','--internal','--label','opsforge.session=06',s.network])
 outcomes={};s.trace['outcomes']=outcomes
 for runtime in (d['baseline'],d['candidate']):
  name,start_seconds=s.create(runtime,d);marker=s.token+'-'+runtime
  s.sql(name,"CREATE EXTENSION pgcrypto; CREATE TABLE marker(value text); INSERT INTO marker VALUES ('"+marker+"');")
  path=s.call(['exec',name,'pg_config','--pkglibdir'])['stdout'].strip()
  assert path=='/usr/local/lib/postgresql','fixed image library location changed'
  module=s.call(['exec',name,'sha256sum',path+'/pgcrypto.so'])['stdout'].split()[0]
  assert len(module)==64
  # A PostgreSQL module resolves backend symbols in postgres, not a standalone loader.
  # Preserve ldd's actual exit/stderr; successful SQL below is the loading/function proof.
  libs=s.call(['exec',name,'ldd',path+'/pgcrypto.so'],check=False)
  assert 'libcrypto' in libs['stdout'],'pgcrypto OpenSSL dependency must be observed'
  digest=s.sql(name,"SELECT encode(digest('"+marker+"','sha256'),'hex');")
  assert digest['stdout'].strip()==hashlib.sha256(marker.encode()).hexdigest()
  proc=s.sql(name,"SELECT DISTINCT probin FROM pg_proc WHERE proname='digest' AND probin='$libdir/pgcrypto';")
  assert proc['stdout'].strip()=='$libdir/pgcrypto','actual C extension function binding required'
  fs=s.call(['exec',name,'/bin/sh','-c','dd if=/dev/zero of=/work/payload bs=1048576 count='+str(d['file_megabytes'])+' && sha256sum /work/payload && stat -c %s /work/payload'])
  assert hashlib.sha256(b'\0'*(d['file_megabytes']*1048576)).hexdigest() in fs['stdout']
  assert fs['stdout'].strip().endswith(str(d['file_megabytes']*1048576))
  table=s.sql(name,"CREATE TABLE samples AS SELECT i, encode(digest(i::text || '"+marker+"','sha256'),'hex') AS h FROM generate_series(1,1024) g(i); SELECT count(*),sum(length(h)),pg_relation_size('samples')>0 FROM samples;")
  assert '1024|65536|t' in table['stdout']
